#### Variation 2: SMART on FHIR for AWS (API Gateway + Cognito + AWS HealthLake)

**Description**: Cloud-native SMART implementation for AWS-hosted state deployments using AWS API Gateway, Cognito for identity, and AWS HealthLake (managed FHIR service).

**Architecture**:
- **API Gateway**: AWS API Gateway with Lambda authorizer for SMART token validation
- **OAuth Server**: AWS Cognito User Pools with custom SMART scope mappings
- **FHIR Server**: AWS HealthLake (managed FHIR R4 service)
- **Token Storage**: Amazon ElastiCache (Redis) for token cache and revocation list

**Lambda Authorizer for SMART Scopes**:

```javascript
// AWS Lambda Authorizer: SMART Token Validation
const jwt = require('jsonwebtoken');
const jwksClient = require('jwks-rsa');

const client = jwksClient({
  jwksUri: 'https://cognito-idp.us-east-1.amazonaws.com/us-east-1_ABC123/.well-known/jwks.json'
});

function getKey(header, callback) {
  client.getSigningKey(header.kid, function(err, key) {
    const signingKey = key.publicKey || key.rsaPublicKey;
    callback(null, signingKey);
  });
}

exports.handler = async (event) => {
  const token = event.authorizationToken.replace('Bearer ', '');

  return new Promise((resolve, reject) => {
    jwt.verify(token, getKey, {}, (err, decoded) => {
      if (err) {
        console.error('Token validation failed:', err);
        reject('Unauthorized');
        return;
      }

      // Extract SMART scopes
      const scopes = decoded.scope ? decoded.scope.split(' ') : [];
      const patientId = decoded.patient;
      const fhirUser = decoded.fhirUser;

      // Build IAM policy based on SMART scopes
      const policy = generatePolicy(decoded.sub, 'Allow', event.methodArn, {
        scopes: JSON.stringify(scopes),
        patientId: patientId || '',
        fhirUser: fhirUser || '',
        clientId: decoded.client_id
      });

      resolve(policy);
    });
  });
};

function generatePolicy(principalId, effect, resource, context) {
  return {
    principalId: principalId,
    policyDocument: {
      Version: '2012-10-17',
      Statement: [{
        Action: 'execute-api:Invoke',
        Effect: effect,
        Resource: resource
      }]
    },
    context: context
  };
}
```

**Best For**: AWS-native deployments, states requiring managed FHIR service, organizations already invested in AWS ecosystem.

