#### Phase 2: Launch Workflows (Weeks 4-6)

**Standalone Launch Implementation:**

```typescript
// Mobile App: SMART Standalone Launch (React Native)
import { authorize } from 'react-native-app-auth';
import { generatePKCE } from './pkce-utils';

interface SMARTConfig {
  issuer: string;
  clientId: string;
  redirectUrl: string;
  fhirBaseUrl: string;
  scopes: string[];
}

async function launchSMARTStandalone(config: SMARTConfig) {
  // Generate PKCE challenge
  const { codeVerifier, codeChallenge } = await generatePKCE();

  // SMART authorization request
  const authResult = await authorize({
    issuer: config.issuer,
    clientId: config.clientId,
    redirectUrl: config.redirectUrl,
    scopes: config.scopes,
    additionalParameters: {
      aud: config.fhirBaseUrl,  // SMART-specific: FHIR server audience
      code_challenge: codeChallenge,
      code_challenge_method: 'S256'
    }
  });

  return {
    accessToken: authResult.accessToken,
    refreshToken: authResult.refreshToken,
    patientId: authResult.tokenAdditionalParameters.patient,  // SMART patient context
    expiresAt: authResult.accessTokenExpirationDate
  };
}

// Usage
const smartTokens = await launchSMARTStandalone({
  issuer: 'https://oauth.gainwell.com',
  clientId: 'gainwell-go-mobile',
  redirectUrl: 'com.gainwell.go://callback',
  fhirBaseUrl: 'https://fhir.gainwell.com',
  scopes: ['patient/*.read', 'offline_access']
});

// Store tokens securely
await SecureStore.setItemAsync('access_token', smartTokens.accessToken);
await SecureStore.setItemAsync('refresh_token', smartTokens.refreshToken);
```

**EHR Launch Implementation:**

```typescript
// Provider Portal: Generate Launch Token
async function generateLaunchToken(clinicalContext: ClinicalContext): Promise<string> {
  const launchPayload = {
    patient: clinicalContext.patientId,
    encounter: clinicalContext.encounterId,
    practitioner: clinicalContext.providerId,
    location: clinicalContext.locationId,
    iss: 'https://fhir.gainwell.com',
    exp: Math.floor(Date.now() / 1000) + 300  // 5-minute expiration
  };

  // Sign with portal's private key
  return jwt.sign(launchPayload, PORTAL_PRIVATE_KEY, { algorithm: 'RS256' });
}

// Launch third-party app from portal
async function launchEHRApp(appUrl: string, clinicalContext: ClinicalContext) {
  const launchToken = await generateLaunchToken(clinicalContext);
  const launchUrl = `${appUrl}?iss=https://fhir.gainwell.com&launch=${launchToken}`;
  window.open(launchUrl, '_blank');
}
